INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich bei einem IT-Projekt immer die teuerste Hardware wählen sollte?', 2, '[{"text": "Nein", "correct": true, "because": "Kosteneffizienz entscheidet"}, {"text": "Ja", "correct": false, "because": "Teuer nicht immer besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend, wenn ich Ressourcen für ein Projekt plane?', 3, '[{"text": "Maximale Leistung bei minimalen Kosten", "correct": true, "because": "Balanciert Effizienz und Budget"}, {"text": "Höchster Preis", "correct": false, "because": "Ignoriert Wirtschaftlichkeit"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Nicht primär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen, ein IT-System kosteneffizient zu betreiben?', 5, '[{"text": "Virtualisierung", "correct": true, "because": "Reduziert Hardwarebedarf"}, {"text": "Automatisierung", "correct": true, "because": "Senkt Arbeitsaufwand"}, {"text": "Maximale Serveranzahl", "correct": false, "because": "Erhöht Kosten"}, {"text": "Bunte Gehäuse", "correct": false, "because": "Kein Effizienzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cloud-Lösungen sind immer günstiger. b) Eigenbetrieb spart langfristig Kosten.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Abhängig von Anwendungsfall"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk kosteneffizient aufbaue?', 4, '[{"text": "Skalierbarkeit", "correct": false, "because": "Ermöglicht Anpassung"}, {"text": "Wartungskosten", "correct": false, "because": "Langfristig relevant"}, {"text": "Router-Design", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die günstigste Lösung immer die beste ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität und Nutzen zählen"}, {"text": "Ja", "correct": false, "because": "Billig kann ineffizient sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategie wähle ich, um Softwarekosten zu senken?', 3, '[{"text": "Open-Source-Nutzung", "correct": true, "because": "Vermeidet Lizenzgebühren"}, {"text": "Teure Eigenentwicklung", "correct": false, "because": "Erhöht Kosten"}, {"text": "Maximale Nutzeranzahl", "correct": false, "because": "Kein Kostenvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein IT-Projekt wirtschaftlich?', 5, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Senkt Ausgaben"}, {"text": "Kosten-Nutzen-Analyse", "correct": true, "because": "Optimiert Entscheidungen"}, {"text": "Hohe Marketingausgaben", "correct": false, "because": "Nicht projektspezifisch"}, {"text": "Luxuriöse Ausstattung", "correct": false, "because": "Kein Effizienzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Outsourcing immer günstiger ist und b) Eigenentwicklung immer teurer ist. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Abhängig von Projektgröße"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein Server-Setup kosteneffizient zu gestalten?', 4, '[{"text": "Energieeffiziente Hardware", "correct": false, "because": "Senkt Betriebskosten"}, {"text": "Virtualisierung", "correct": false, "because": "Optimiert Ressourcen"}, {"text": "Goldene Kabel", "correct": true, "because": "Kein Effizienzvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Preis allein entscheidend für eine IT-Lösung?', 2, '[{"text": "Nein", "correct": true, "because": "Leistung und Wartung zählen"}, {"text": "Ja", "correct": false, "because": "Gesamtkosten entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen senken langfristige Kosten eines Netzwerks?', 4, '[{"text": "Standardisierte Komponenten", "correct": true, "because": "Vereinfacht Wartung"}, {"text": "Automatisierte Updates", "correct": true, "because": "Reduziert Arbeitsaufwand"}, {"text": "Maximale Bandbreite", "correct": false, "because": "Erhöht Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Cloud-Dienste immer die günstigste Option sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nutzung"}, {"text": "Ja", "correct": false, "because": "On-Premise kann günstiger sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine kosteneffiziente Software auswähle?', 3, '[{"text": "Passende Funktionalität", "correct": true, "because": "Vermeidet Überkosten"}, {"text": "Maximale Features", "correct": false, "because": "Kann Kosten erhöhen"}, {"text": "Schickes Design", "correct": false, "because": "Kein Kostenvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Skalierbarkeit spart Kosten. b) Mehr Hardware ist immer günstiger.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mehr Hardware erhöht Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft mir, die günstigste Hardware zu finden?', 4, '[{"text": "Gesamtbetriebskosten berechnen", "correct": true, "because": "Berücksichtigt Langzeitkosten"}, {"text": "Nur Anschaffungspreis prüfen", "correct": false, "because": "Ignoriert Betrieb"}, {"text": "Schnellste Lieferung wählen", "correct": false, "because": "Kein Kostenkriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Standardsoftware immer günstiger als Individualsoftware ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Individual kann langfristig sparen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine IT-Lösung kosteneffizient?', 5, '[{"text": "Langlebige Hardware", "correct": true, "because": "Reduziert Ersatzkosten"}, {"text": "Automatisierte Prozesse", "correct": true, "because": "Senkt Arbeitsaufwand"}, {"text": "Maximale Nutzeranzahl", "correct": false, "because": "Kann Kosten erhöhen"}, {"text": "Luxusausstattung", "correct": false, "because": "Kein Effizienzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Spart Outsourcing immer Geld?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Projektumfang"}, {"text": "Ja", "correct": false, "because": "Kann teurer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Vorgehen wähle ich, um ein Projektbudget einzuhalten?', 4, '[{"text": "Kosten-Nutzen-Analyse", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Maximale Ausgaben", "correct": false, "because": "Überschreitet Budget"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Ineffizient"}]');
